#[derive(Debug, Serialize)]
struct LocalShowRequest<'a> {
    model: &'a str,
}

#[derive(Debug, Default, Deserialize)]
struct LocalShowResponse {
    #[serde(default)]
    capabilities: Vec<String>,
}

fn discover_model_capabilities(
    endpoint: &LocalHttpEndpoint,
    model: &str,
) -> Vec<String> {
    let body = match serde_json::to_vec(&LocalShowRequest { model }) {
        Ok(body) => body,
        Err(_) => return Vec::new(),
    };
    let Ok(response) = request_local_json::<LocalShowResponse>(
        endpoint,
        "POST",
        "/api/show",
        Some(&body),
    ) else {
        return Vec::new();
    };
    let mut capabilities = response
        .capabilities
        .into_iter()
        .map(|capability| capability.trim().to_ascii_lowercase())
        .filter(|capability| !capability.is_empty())
        .collect::<Vec<_>>();
    capabilities.sort();
    capabilities.dedup();
    capabilities
}

